// src/output/sarif.ts
function buildSarif(findings) {
  const rules = findings.map((f2, idx) => ({
    id: `RULE-${idx + 1}`,
    shortDescription: { text: f2.title },
    fullDescription: { text: f2.message },
    defaultConfiguration: { level: severityToLevel(f2.severity) }
  }));
  const results = findings.map((f2, idx) => ({
    ruleId: `RULE-${idx + 1}`,
    level: severityToLevel(f2.severity),
    message: { text: f2.message },
    locations: [
      {
        physicalLocation: {
          artifactLocation: { uri: f2.file },
          region: { startLine: f2.line }
        }
      }
    ]
  }));
  return {
    version: "2.1.0",
    $schema: "http://json.schemastore.org/sarif-2.1.0.json",
    runs: [
      {
        tool: {
          driver: {
            name: "review-router",
            version: "2.0.0",
            informationUri: "https://github.com/777genius/review-router",
            rules
          }
        },
        results
      }
    ]
  };
}
